pub(crate) fn attach_started_ask_session(
    &mut self,
    host: &AgentHost,
    agent_id: &str,
    runtime: Box<dyn AcpAgentRuntime>,
    mut session: Box<dyn AcpAgentSession>,
    gameengine_session_id: &str,
) -> Result<String, AcpBridgeError> {
    let descriptor_id = runtime.descriptor().id.clone();
    if descriptor_id != agent_id {
        let _ = session.close();
        return Err(AcpBridgeError::BindingMismatch(format!(
            "ACP startup returned descriptor `{descriptor_id}` for requested agent `{agent_id}`"
        )));
    }
    self.registry.replace(runtime)?;
    self.bridge.attach_ask_session(
        host,
        descriptor_id,
        session,
        gameengine_session_id,
    )
}

